    '14-07-007': ['kan', 'полиэтиленовые', 0, 1, '4', [74, 75], [[160, [[2, 8567.06], [3, 10911.99], [4, 156292.18], [5, 184562.11]]], [200, [[2, 8308.39], [3, 10396.12], [4, 153051.15], [5, 181457.33]]], [315, [[2, 10964.21], [3, 12265.5], [4, 154064.14], [5, 182159.6]]], [400, [[2, 11280.59], [3, 13587.33], [4, 155314.51], [5, 183473.96]]], [500, [[2, 12875.39], [3, 23137.91], [4, 155857.23], [5, 183642.56]]], [630, [[3, 28130.51], [4, 159516.43], [5, 187741.01]]], [800, [[3, 37038.41], [4, 167062.7], [5, 197289.97]]], [1000, [[3, 45945.91], [4, 178110.26], [5, 205686.56]]]]],
